function MetricCard({ label, value, note, icon: Icon, accent = 'gold' }: { label: string; value: string; note: string; icon: typeof Users; accent?: 'gold' | 'coral' | 'blue' | 'green' }) {
  const colors = { gold: 'bg-[hsl(var(--secondary)/.2)] text-[#806015]', coral: 'bg-[hsl(var(--accent)/.15)] text-[#a2473d]', blue: 'bg-[#dcecef] text-[#245e6d]', green: 'bg-[#dceee3] text-[#286342]' };
  return <Card className="relative overflow-hidden p-4 sm:p-5"><div className="mb-5 flex items-start justify-between"><span className="text-xs font-bold text-[hsl(var(--muted-foreground))]">{label}</span><span className={`grid h-8 w-8 place-items-center rounded-lg ${colors[accent]}`}><Icon size={16} /></span></div><p className="font-display text-[27px] font-semibold tracking-[-.04em]">{value}</p><p className="mt-1 text-[11px] font-medium text-[hsl(var(--muted-foreground))]">{note}</p><div className={`absolute bottom-0 left-0 h-1 w-1/3 ${accent === 'gold' ? 'bg-[hsl(var(--secondary))]' : accent === 'coral' ? 'bg-[hsl(var(--accent))]' : accent === 'blue' ? 'bg-[#4f91a0]' : 'bg-[#6eae87]'}`} /></Card>;
}

